    "body": "import java.time.Duration;\nimport java.time.Instant;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\nimport java.util.concurrent.ConcurrentHashMap;\nimport java.util.concurrent.CountDownLatch;\nimport java.util.concurrent.ExecutorService;\nimport java.util.concurrent.Executors;\nimport java.util.concurrent.TimeUnit;\n\npublic class Tests {\n    static MutableClock clock;\n\n    static ParkingLot lot(SpotAllocationStrategy alloc, PricingStrategy pricing, SpotSize... sizes) {\n        clock = new MutableClock(Instant.parse(\"2026-01-01T09:00:00Z\"));\n        List<ParkingSpot> spots = new ArrayList<>();\n        for (int i = 0; i < sizes.length; i++) spots.add(new ParkingSpot(0, i + 1, sizes[i]));\n        return new ParkingLot(List.of(new ParkingFloor(0, spots)), alloc, pricing, clock);\n    }\n\n    static PricingStrategy hourly() {\n        return new HourlyPricing(Map.of(VehicleType.MOTORCYCLE, 10L, VehicleType.CAR, 20L, VehicleType.TRUCK, 40L));\n    }\n\n    static void check(boolean cond, String name) {\n        if (!cond) throw new AssertionError(\"FAIL: \" + name);\n        System.out.println(\"PASS: \" + name);\n    }\n\n    static <T extends Throwable> void expect(Class<T> type, Runnable r, String name) {\n        try {\n            r.run();\n        } catch (Throwable t) {\n            check(type.isInstance(t), name);\n            return;\n        }\n        throw new AssertionError(\"FAIL (nothing thrown): \" + name);\n    }\n\n    public static void main(String[] args) throws Exception {\n        ParkingLot l = lot(new BestFitAllocation(), hourly(), SpotSize.LARGE, SpotSize.MEDIUM, SpotSize.SMALL);\n        Ticket bike = l.enter(new Vehicle(\"B1\", VehicleType.MOTORCYCLE));\n        check(bike.spot().size() == SpotSize.SMALL, \"motorcycle takes the smallest spot\");\n        Ticket car = l.enter(new Vehicle(\"C1\", VehicleType.CAR));\n        check(car.spot().size() == SpotSize.MEDIUM, \"car takes a medium spot\");\n        Ticket truck = l.enter(new Vehicle(\"T1\", VehicleType.TRUCK));\n        check(truck.spot().size() == SpotSize.LARGE, \"truck takes the large spot\");\n        expect(ParkingFullException.class, () -> l.enter(new Vehicle(\"C2\", VehicleType.CAR)), \"full lot rejects entry\");\n\n        ParkingLot l2 = lot(new BestFitAllocation(), hourly(), SpotSize.LARGE);\n        check(l2.enter(new Vehicle(\"B1\", VehicleType.MOTORCYCLE)).spot().size() == SpotSize.LARGE,\n                \"small vehicle may use a larger spot when nothing else is free\");\n\n        ParkingLot l3 = lot(new BestFitAllocation(), hourly(), SpotSize.SMALL);\n        expect(ParkingFullException.class, () -> l3.enter(new Vehicle(\"T1\", VehicleType.TRUCK)),\n                \"truck never fits a small spot\");\n\n        ParkingLot l4 = lot(new BestFitAllocation(), hourly(), SpotSize.MEDIUM, SpotSize.MEDIUM);\n        Ticket t = l4.enter(new Vehicle(\"C1\", VehicleType.CAR));\n        expect(IllegalStateException.class, () -> l4.enter(new Vehicle(\"C1\", VehicleType.CAR)), \"same plate cannot park twice\");\n        check(l4.freeSpots() == 1, \"rejected duplicate does not leak a spot\");\n        clock.advance(Duration.ofMinutes(1));\n        check(l4.exit(t.id()) == 20, \"stay under an hour is billed one hour\");\n        check(l4.freeSpots() == 2, \"exit frees the spot\");\n        expect(IllegalArgumentException.class, () -> l4.exit(t.id()), \"ticket cannot be used twice\");\n\n        ParkingLot l5 = lot(new BestFitAllocation(), hourly(), SpotSize.MEDIUM);\n        Ticket c5 = l5.enter(new Vehicle(\"C5\", VehicleType.CAR));\n        clock.advance(Duration.ofMinutes(61));\n        check(l5.exit(c5.id()) == 40, \"61 minutes rounds up to two hours\");\n\n        ParkingLot l6 = lot(new BestFitAllocation(), hourly(), SpotSize.MEDIUM);\n        Ticket c6 = l6.enter(new Vehicle(\"C6\", VehicleType.CAR));\n        clock.advance(Duration.ofHours(3));\n        l6.setPricing(new FlatPricing(99));\n        check(l6.exit(c6.id()) == 99, \"pricing strategy can be swapped at runtime\");\n\n        ParkingLot l7 = lot(new FirstAvailableAllocation(), hourly(), SpotSize.LARGE, SpotSize.MEDIUM);\n        check(l7.enter(new Vehicle(\"C7\", VehicleType.CAR)).spot().size() == SpotSize.LARGE,\n                \"first-available strategy takes the first fitting spot\");\n\n        ParkingLot race = lot(new BestFitAllocation(), hourly(),\n                SpotSize.MEDIUM, SpotSize.MEDIUM, SpotSize.MEDIUM, SpotSize.MEDIUM, SpotSize.MEDIUM);\n        ExecutorService pool = Executors.newFixedThreadPool(32);\n        CountDownLatch go = new CountDownLatch(1);\n        Set<String> used = ConcurrentHashMap.newKeySet();\n        java.util.concurrent.atomic.AtomicInteger ok = new java.util.concurrent.atomic.AtomicInteger();\n        for (int i = 0; i < 100; i++) {\n            final int n = i;\n            pool.submit(() -> {\n                try {\n                    go.await();\n                    Ticket tk = race.enter(new Vehicle(\"R\" + n, VehicleType.CAR));\n                    used.add(tk.spot().id());\n                    ok.incrementAndGet();\n                } catch (ParkingFullException ignored) {\n                } catch (InterruptedException e) {\n                    Thread.currentThread().interrupt();\n                }\n            });\n        }\n        go.countDown();\n        pool.shutdown();\n        pool.awaitTermination(10, TimeUnit.SECONDS);\n        check(ok.get() == 5 && used.size() == 5, \"100 racing cars fill exactly 5 spots with no duplicates\");\n        check(race.freeSpots() == 0, \"no spot left free after the race\");\n    }\n}",
