      "file": "User.java",
      "body": "import java.util.concurrent.atomic.AtomicInteger;\n\npublic class User {\n    private final long id;\n    private final String name;\n    private final AtomicInteger reputation = new AtomicInteger(1);\n\n    public User(long id, String name) {\n        this.id = id;\n        this.name = name;\n    }\n\n    public long id() { return id; }\n    public String name() { return name; }\n    public int reputation() { return reputation.get(); }\n\n    /** Atomic and floored at 1, like the real site. */\n    public void adjustReputation(int delta) {\n        reputation.updateAndGet(r -> Math.max(1, r + delta));\n    }\n\n    @Override\n    public String toString() { return name; }\n}"
