    "text": "The demo posts, answers and comments, votes (including a vote change, a self-vote and a repeat vote), accepts an answer, swaps the reputation policy, searches with combined filters, then runs 100 users voting at once and one user voting 50 times at once. Compile everything with `javac -d out *.java`, then run `java -cp out Main`.",
    "file": "Main.java",
    "body": "import java.util.ArrayList;\nimport java.util.List;\nimport java.util.Set;\nimport java.util.concurrent.CountDownLatch;\nimport java.util.concurrent.ExecutorService;\nimport java.util.concurrent.Executors;\nimport java.util.concurrent.TimeUnit;\nimport java.util.concurrent.atomic.AtomicInteger;\n\npublic class Main {\n    static void rep(String label, User... users) {\n        StringBuilder sb = new StringBuilder(label);\n        for (User u : users) sb.append(' ').append(u).append('=').append(u.reputation());\n        System.out.println(sb);\n    }\n\n    static void attempt(String label, Runnable r) {\n        try {\n            r.run();\n            System.out.println(label + \": ok\");\n        } catch (RuntimeException e) {\n            System.out.println(label + \": rejected (\" + e.getMessage() + \")\");\n        }\n    }\n\n    public static void main(String[] args) throws Exception {\n        StackOverflow so = new StackOverflow(new DefaultReputationPolicy());\n        User alice = so.register(\"alice\"), bob = so.register(\"bob\"), carol = so.register(\"carol\"),\n                dave = so.register(\"dave\"), erin = so.register(\"erin\");\n\n        System.out.println(\"== Requirement 1: post, answer, comment ==\");\n        Question q1 = so.ask(alice, \"How do I reverse a linked list?\", \"Iteratively in Java, please.\", Set.of(\"Java\", \"linked-list\"));\n        Question q2 = so.ask(bob, \"HashMap vs Hashtable\", \"Which one should I use?\", Set.of(\"java\", \"collections\"));\n        Question q3 = so.ask(carol, \"Python list comprehension\", \"Syntax help needed.\", Set.of(\"python\"));\n        Answer a1 = so.answer(q1, bob, \"Keep prev/curr/next pointers and flip each link.\");\n        Answer a2 = so.answer(q1, carol, \"Use recursion.\");\n        so.comment(q1, dave, \"Which Java version?\");\n        so.comment(a1, alice, \"This worked, thanks!\");\n        System.out.println(q1.title() + \" -> answers=\" + q1.answers().size() + \", comments on question=\" + q1.comments().size()\n                + \", comments on first answer=\" + a1.comments().size());\n        rep(\"Start:\", alice, bob, carol, dave, erin);\n\n        System.out.println(\"== Requirement 2: voting, one vote per user ==\");\n        so.vote(dave, q1, VoteType.UP);\n        so.vote(carol, a1, VoteType.UP);\n        so.vote(dave, a1, VoteType.UP);\n        so.vote(dave, a2, VoteType.DOWN);\n        rep(\"After votes:\", alice, bob, carol);\n        so.vote(erin, a1, VoteType.DOWN);\n        System.out.println(\"Answer 1 score after erin downvotes: \" + a1.score());\n        so.vote(erin, a1, VoteType.UP);\n        System.out.println(\"Answer 1 score after erin switches to upvote: \" + a1.score());\n        rep(\"After switch:\", bob);\n        attempt(\"alice votes on her own question\", () -> so.vote(alice, q1, VoteType.UP));\n        attempt(\"dave upvotes answer 1 again\", () -> so.vote(dave, a1, VoteType.UP));\n\n        System.out.println(\"== Accepting an answer ==\");\n        attempt(\"bob tries to accept his own answer\", () -> so.accept(a1, bob));\n        attempt(\"alice accepts answer 1\", () -> so.accept(a1, alice));\n        attempt(\"alice accepts answer 2 as well\", () -> so.accept(a2, alice));\n        rep(\"After accept:\", alice, bob);\n\n        System.out.println(\"== Requirement 3: reputation policy is pluggable ==\");\n        StackOverflow promo = new StackOverflow(new DoublePointsPolicy());\n        User p1 = promo.register(\"p1\"), p2 = promo.register(\"p2\");\n        Question pq = promo.ask(p1, \"Promo question\", \"body\", Set.of(\"promo\"));\n        Answer pa = promo.answer(pq, p1, \"self answer\");\n        promo.vote(p2, pa, VoteType.UP);\n        rep(\"Double-points upvote on an answer:\", p1);\n\n        System.out.println(\"== Requirement 4: search with composable filters ==\");\n        show(\"tag java\", so.search().search(Filters.tag(\"java\")));\n        show(\"keyword hashmap\", so.search().search(Filters.keyword(\"hashmap\")));\n        show(\"tag java AND author bob\", so.search().search(Filters.tag(\"java\"), Filters.author(bob)));\n        show(\"has accepted answer\", so.search().search(Filters.hasAcceptedAnswer()));\n        show(\"tag rust\", so.search().search(Filters.tag(\"rust\")));\n\n        System.out.println(\"== Concurrency ==\");\n        Question cq = so.ask(alice, \"Concurrent voting\", \"body\", Set.of(\"java\"));\n        Answer ca = so.answer(cq, bob, \"answer\");\n        int before = bob.reputation();\n        int voters = 100;\n        ExecutorService pool = Executors.newFixedThreadPool(32);\n        CountDownLatch go = new CountDownLatch(1);\n        List<User> users = new ArrayList<>();\n        for (int i = 0; i < voters; i++) users.add(so.register(\"v\" + i));\n        for (User u : users) {\n            pool.submit(() -> {\n                try {\n                    go.await();\n                    so.vote(u, ca, VoteType.UP);\n                } catch (InterruptedException e) {\n                    Thread.currentThread().interrupt();\n                }\n            });\n        }\n        go.countDown();\n        pool.shutdown();\n        pool.awaitTermination(10, TimeUnit.SECONDS);\n        System.out.println(voters + \" distinct users upvote at once -> score=\" + ca.score()\n                + \", bob reputation gained=\" + (bob.reputation() - before));\n\n        Answer ca2 = so.answer(cq, carol, \"another answer\");\n        User spammer = so.register(\"spammer\");\n        ExecutorService pool2 = Executors.newFixedThreadPool(32);\n        CountDownLatch go2 = new CountDownLatch(1);\n        AtomicInteger accepted = new AtomicInteger();\n        AtomicInteger rejected = new AtomicInteger();\n        for (int i = 0; i < 50; i++) {\n            pool2.submit(() -> {\n                try {\n                    go2.await();\n                    so.vote(spammer, ca2, VoteType.UP);\n                    accepted.incrementAndGet();\n                } catch (IllegalStateException e) {\n                    rejected.incrementAndGet();\n                } catch (InterruptedException e) {\n                    Thread.currentThread().interrupt();\n                }\n            });\n        }\n        go2.countDown();\n        pool2.shutdown();\n        pool2.awaitTermination(10, TimeUnit.SECONDS);\n        System.out.println(\"50 upvotes from the same user -> counted=\" + accepted + \" rejected=\" + rejected\n                + \" score=\" + ca2.score());\n    }\n\n    static void show(String label, List<Question> qs) {\n        StringBuilder sb = new StringBuilder(label + \": \");\n        if (qs.isEmpty()) sb.append(\"(none)\");\n        for (int i = 0; i < qs.size(); i++) {\n            if (i > 0) sb.append(\" | \");\n            sb.append(qs.get(i).title()).append(\" [\").append(qs.get(i).score()).append(\"]\");\n        }\n        System.out.println(sb);\n    }\n}",
