    "body": "import java.util.ArrayList;\nimport java.util.List;\nimport java.util.Set;\nimport java.util.concurrent.CountDownLatch;\nimport java.util.concurrent.ExecutorService;\nimport java.util.concurrent.Executors;\nimport java.util.concurrent.TimeUnit;\nimport java.util.concurrent.atomic.AtomicInteger;\n\npublic class Tests {\n    static void check(boolean cond, String name) {\n        if (!cond) throw new AssertionError(\"FAIL: \" + name);\n        System.out.println(\"PASS: \" + name);\n    }\n\n    static <T extends Throwable> void expect(Class<T> type, Runnable r, String name) {\n        try {\n            r.run();\n        } catch (Throwable t) {\n            check(type.isInstance(t), name);\n            return;\n        }\n        throw new AssertionError(\"FAIL (nothing thrown): \" + name);\n    }\n\n    public static void main(String[] args) throws Exception {\n        StackOverflow so = new StackOverflow(new DefaultReputationPolicy());\n        User asker = so.register(\"asker\"), helper = so.register(\"helper\"), voter = so.register(\"voter\"), other = so.register(\"other\");\n        Question q = so.ask(asker, \"Sorting a list\", \"How?\", Set.of(\"Java\", \"Sorting\"));\n        Answer a = so.answer(q, helper, \"Use Collections.sort\");\n\n        check(q.tags().equals(Set.of(\"java\", \"sorting\")), \"tags are normalised to lower case\");\n        so.comment(a, asker, \"Thanks\");\n        check(a.comments().size() == 1, \"comments attach to answers\");\n\n        so.vote(voter, q, VoteType.UP);\n        check(q.score() == 1 && asker.reputation() == 6, \"question upvote gives +5 reputation\");\n        so.vote(voter, a, VoteType.UP);\n        check(a.score() == 1 && helper.reputation() == 11, \"answer upvote gives +10 reputation\");\n        so.vote(voter, a, VoteType.DOWN);\n        check(a.score() == -1 && helper.reputation() == 1, \"changing UP to DOWN swings the score by 2 and floors reputation at 1\");\n        expect(IllegalStateException.class, () -> so.vote(voter, a, VoteType.DOWN), \"same vote twice is rejected\");\n        expect(IllegalStateException.class, () -> so.vote(helper, a, VoteType.UP), \"cannot vote on own post\");\n\n        User newbie = so.register(\"newbie\");\n        Question q2 = so.ask(newbie, \"x\", \"y\", Set.of());\n        Answer a2 = so.answer(q2, helper, \"z\");\n        so.vote(other, a2, VoteType.DOWN);\n        so.vote(voter, a2, VoteType.DOWN);\n        check(helper.reputation() == 1, \"reputation never drops below 1\");\n\n        expect(IllegalStateException.class, () -> so.accept(a, helper), \"only the asker can accept\");\n        so.accept(a, asker);\n        check(q.accepted() == a, \"asker can accept an answer\");\n        check(helper.reputation() == 16 && asker.reputation() == 8, \"accepting pays answerer +15 and asker +2\");\n        Answer a3 = so.answer(q, other, \"alt\");\n        expect(IllegalStateException.class, () -> so.accept(a3, asker), \"only one accepted answer\");\n        expect(IllegalArgumentException.class, () -> q.accept(a2, asker), \"answer must belong to the question\");\n\n        Question q3 = so.ask(helper, \"HashMap internals\", \"Explain buckets\", Set.of(\"java\", \"collections\"));\n        check(so.search().search(Filters.tag(\"java\")).size() == 2, \"tag filter\");\n        check(so.search().search(Filters.tag(\"JAVA\")).size() == 2, \"tag filter ignores case\");\n        check(so.search().search(Filters.keyword(\"buckets\")).get(0) == q3, \"keyword filter searches the body\");\n        check(so.search().search(Filters.tag(\"java\"), Filters.author(helper)).size() == 1, \"filters combine with AND\");\n        check(so.search().search().size() == 3, \"no filters returns everything\");\n        check(so.search().search(Filters.tag(\"java\")).get(0) == q, \"results are ordered by score\");\n        check(so.search().search(Filters.hasAcceptedAnswer()).size() == 1, \"custom filter plugs in\");\n        check(so.search().search(Filters.tag(\"none\")).isEmpty(), \"no match returns empty list\");\n\n        StackOverflow promo = new StackOverflow(new DoublePointsPolicy());\n        User p1 = promo.register(\"p1\"), p2 = promo.register(\"p2\");\n        Answer pa = promo.answer(promo.ask(p1, \"t\", \"b\", Set.of()), p1, \"a\");\n        promo.vote(p2, pa, VoteType.UP);\n        check(p1.reputation() == 21, \"swapping the reputation policy changes points without other edits\");\n\n        Question cq = so.ask(asker, \"Race\", \"body\", Set.of());\n        Answer ca = so.answer(cq, helper, \"answer\");\n        int before = helper.reputation();\n        List<User> users = new ArrayList<>();\n        for (int i = 0; i < 200; i++) users.add(so.register(\"u\" + i));\n        ExecutorService pool = Executors.newFixedThreadPool(32);\n        CountDownLatch go = new CountDownLatch(1);\n        for (User u : users) {\n            pool.submit(() -> {\n                try {\n                    go.await();\n                    so.vote(u, ca, VoteType.UP);\n                } catch (InterruptedException e) {\n                    Thread.currentThread().interrupt();\n                }\n            });\n        }\n        go.countDown();\n        pool.shutdown();\n        pool.awaitTermination(10, TimeUnit.SECONDS);\n        check(ca.score() == 200, \"200 concurrent upvoters give score 200\");\n        check(helper.reputation() - before == 2000, \"reputation is exactly 200 x 10 under concurrency\");\n\n        User dup = so.register(\"dup\");\n        Answer ca2 = so.answer(cq, other, \"second\");\n        ExecutorService pool2 = Executors.newFixedThreadPool(32);\n        CountDownLatch go2 = new CountDownLatch(1);\n        AtomicInteger counted = new AtomicInteger();\n        for (int i = 0; i < 100; i++) {\n            pool2.submit(() -> {\n                try {\n                    go2.await();\n                    so.vote(dup, ca2, VoteType.UP);\n                    counted.incrementAndGet();\n                } catch (IllegalStateException ignored) {\n                } catch (InterruptedException e) {\n                    Thread.currentThread().interrupt();\n                }\n            });\n        }\n        go2.countDown();\n        pool2.shutdown();\n        pool2.awaitTermination(10, TimeUnit.SECONDS);\n        check(counted.get() == 1 && ca2.score() == 1, \"one user racing against themselves counts once\");\n    }\n}",
    "output": "PASS: tags are normalised to lower case\nPASS: comments attach to answers\nPASS: question upvote gives +5 reputation\nPASS: answer upvote gives +10 reputation\nPASS: changing UP to DOWN swings the score by 2 and floors reputation at 1\nPASS: same vote twice is rejected\nPASS: cannot vote on own post\nPASS: reputation never drops below 1\nPASS: only the asker can accept\nPASS: asker can accept an answer\nPASS: accepting pays answerer +15 and asker +2\nPASS: only one accepted answer\nPASS: answer must belong to the question\nPASS: tag filter\nPASS: tag filter ignores case\nPASS: keyword filter searches the body\nPASS: filters combine with AND\nPASS: no filters returns everything\nPASS: results are ordered by score\nPASS: custom filter plugs in\nPASS: no match returns empty list\nPASS: swapping the reputation policy changes points without other edits\nPASS: 200 concurrent upvoters give score 200\nPASS: reputation is exactly 200 x 10 under concurrency\nPASS: one user racing against themselves counts once"
