          "body": "import java.util.Map;\n\npublic interface VendingState {\n    void insert(VendingMachine machine, Coin coin);\n\n    Sale select(VendingMachine machine, String code);\n\n    Map<Coin, Integer> cancel(VendingMachine machine);\n\n    Sale payByCard(VendingMachine machine, String code, PaymentMethod card);\n\n    /** Technicians may only open the machine when no customer is mid-transaction. */\n    default boolean allowsMaintenance() { return false; }\n\n    String name();\n}"
