          "file": "IdleState.java",
          "body": "import java.util.Map;\n\npublic class IdleState implements VendingState {\n    @Override\n    public void insert(VendingMachine m, Coin coin) {\n        m.addToEscrow(coin);\n        m.setState(new HasMoneyState());\n    }\n\n    @Override\n    public Sale select(VendingMachine m, String code) {\n        throw new VendingException(\"Insert money first\");\n    }\n\n    @Override\n    public Map<Coin, Integer> cancel(VendingMachine m) {\n        return Map.of();\n    }\n\n    @Override\n    public Sale payByCard(VendingMachine m, String code, PaymentMethod card) {\n        return m.completeCardSale(code, card);\n    }\n\n    @Override public boolean allowsMaintenance() { return true; }\n    @Override public String name() { return \"IDLE\"; }\n}"
