    "body": "import java.nio.file.Files;\nimport java.nio.file.Path;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.concurrent.CountDownLatch;\nimport java.util.concurrent.atomic.AtomicInteger;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        Clock clock = Clock.fixed(Instant.parse(\"2026-01-01T09:00:00Z\"), ZoneOffset.UTC);\n        LoggerFactory factory = new LoggerFactory(LogLevel.INFO, clock);\n\n        System.out.println(\"== Requirement 1 and 3: levels, threshold, one destination ==\");\n        factory.addAppender(new ConsoleAppender(System.out, new SimpleFormatter()));\n        Logger orders = factory.getLogger(\"com.shop.Orders\");\n        orders.debug(\"cart loaded (dropped: below INFO)\");\n        orders.info(\"order 42 created\");\n        orders.warn(\"payment slow\");\n        orders.error(\"payment failed\");\n        orders.fatal(\"database unreachable\");\n        orders.setLevel(LogLevel.ERROR);\n        orders.warn(\"hidden now, threshold is ERROR\");\n        orders.error(\"only ERROR and FATAL pass\");\n        orders.setLevel(LogLevel.DEBUG);\n        orders.debug(\"debug visible again\");\n        orders.setLevel(LogLevel.INFO);\n\n        System.out.println(\"== Lazy messages are only built when enabled ==\");\n        AtomicInteger built = new AtomicInteger();\n        orders.debug(() -> \"expensive \" + built.incrementAndGet());\n        System.out.println(\"Suppliers evaluated while DEBUG is off: \" + built.get());\n        orders.setLevel(LogLevel.DEBUG);\n        orders.debug(() -> \"expensive \" + built.incrementAndGet());\n        System.out.println(\"Suppliers evaluated while DEBUG is on: \" + built.get());\n        orders.setLevel(LogLevel.INFO);\n\n        System.out.println(\"== Requirement 2 and 4: several destinations, a format each ==\");\n        MemoryAppender json = new MemoryAppender(new JsonFormatter());\n        Path errorFile = Files.createTempFile(\"errors\", \".log\");\n        factory.addAppender(json);\n        factory.addAppender(new LevelFilterAppender(LogLevel.ERROR, new FileAppender(errorFile, new SimpleFormatter())));\n        orders.info(\"order 43 created\");\n        orders.error(\"charge declined\", new IllegalStateException(\"card \\\"expired\\\"\"));\n        System.out.println(\"JSON destination:\");\n        json.lines().forEach(l -> System.out.println(\"  \" + l));\n\n        System.out.println(\"== Same name, same logger ==\");\n        System.out.println(\"getLogger twice returns the same instance: \" + (factory.getLogger(\"com.shop.Orders\") == orders));\n        System.out.println(\"Different name is a different logger: \" + (factory.getLogger(\"com.shop.Billing\") != orders));\n\n        System.out.println(\"== A failing destination does not silence the others ==\");\n        factory.addAppender(e -> { throw new RuntimeException(\"disk full\"); });\n        long before = json.lines().size();\n        orders.info(\"still delivered\");\n        System.out.println(\"Lines in JSON destination: +\" + (json.lines().size() - before) + \", appender failures counted: \" + orders.appenderFailures());\n\n        System.out.println(\"== Slow destinations must not block application threads ==\");\n        LoggerFactory slowFactory = new LoggerFactory(LogLevel.INFO, clock);\n        MemoryAppender sink = new MemoryAppender(new SimpleFormatter());\n        AsyncAppender async = new AsyncAppender(e -> {\n            try {\n                Thread.sleep(20);\n            } catch (InterruptedException ex) {\n                Thread.currentThread().interrupt();\n            }\n            sink.append(e);\n        }, 1000);\n        slowFactory.addAppender(async);\n        Logger slow = slowFactory.getLogger(\"slow\");\n        long start = System.nanoTime();\n        for (int i = 0; i < 50; i++) slow.info(\"event \" + i);\n        long appMillis = (System.nanoTime() - start) / 1_000_000;\n        System.out.println(\"50 events logged by the app thread in under 500 ms (delivery needs ~1000 ms): \" + (appMillis < 500));\n        slowFactory.shutdown();\n        System.out.println(\"After shutdown, delivered=\" + sink.lines().size() + \" dropped=\" + async.dropped());\n\n        System.out.println(\"== Full queue drops instead of blocking ==\");\n        CountDownLatch release = new CountDownLatch(1);\n        AsyncAppender tiny = new AsyncAppender(e -> {\n            try {\n                release.await();\n            } catch (InterruptedException ex) {\n                Thread.currentThread().interrupt();\n            }\n        }, 5);\n        LoggerFactory tinyFactory = new LoggerFactory(LogLevel.INFO, clock);\n        tinyFactory.addAppender(tiny);\n        Logger t = tinyFactory.getLogger(\"tiny\");\n        for (int i = 0; i < 100; i++) t.info(\"burst \" + i);\n        System.out.println(\"100 events into a stuck destination with queue size 5 -> dropped >= 94: \" + (tiny.dropped() >= 94));\n        release.countDown();\n        tinyFactory.shutdown();\n\n        System.out.println(\"== Concurrency: no interleaved lines ==\");\n        java.io.ByteArrayOutputStream bytes = new java.io.ByteArrayOutputStream();\n        LoggerFactory busy = new LoggerFactory(LogLevel.INFO, clock);\n        busy.addAppender(new ConsoleAppender(new java.io.PrintStream(bytes, true), new SimpleFormatter()));\n        Logger shared = busy.getLogger(\"busy\");\n        List<Thread> threads = new ArrayList<>();\n        for (int i = 0; i < 8; i++) {\n            final int n = i;\n            Thread th = new Thread(() -> {\n                for (int j = 0; j < 500; j++) shared.info(\"worker-\" + n + \" message \" + j + \" end\");\n            }, \"w\" + i);\n            threads.add(th);\n            th.start();\n        }\n        for (Thread th : threads) th.join();\n        String[] lines = bytes.toString().split(\"\\n\");\n        long intact = java.util.Arrays.stream(lines)\n                .filter(l -> l.matches(\"2026-01-01T09:00:00Z \\\\[INFO\\\\] \\\\[w\\\\d\\\\] busy - worker-\\\\d message \\\\d+ end\"))\n                .count();\n        System.out.println(\"Lines written=\" + lines.length + \" intact=\" + intact);\n\n        System.out.println(\"== File destination received only ERROR and above ==\");\n        factory.shutdown();\n        Files.readAllLines(errorFile).forEach(l -> System.out.println(\"  \" + l));\n        Files.deleteIfExists(errorFile);\n    }\n}",
